export function getCowSettlementErrorMessage(code: CowSettlementError): string {
  if (process.env["NODE_ENV"] !== "production") {
    return (cowSettlementErrorMessages as Record<CowSettlementError, string>)[code];
  }

  return "Error message not available in production bundles.";
}

export function isCowSettlementError<TProgramErrorCode extends CowSettlementError>(
  error: unknown,
  transactionMessage: { instructions: Record<number, { programAddress: Address }> },
  code?: TProgramErrorCode,
): error is SolanaError<typeof SOLANA_ERROR__INSTRUCTION_ERROR__CUSTOM> &
  Readonly<{ context: Readonly<{ code: TProgramErrorCode }> }> {
  return isProgramError<TProgramErrorCode>(
    error,
    transactionMessage,
    COW_SETTLEMENT_PROGRAM_ADDRESS,
    code,
  );
}
